1	import { useMemo, useState } from "react";
2	import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
3	import { useLocation } from "wouter";
4	import { tradesFetch, tradesHeaders } from "@/lib/trades-api";
5	import { formatNzd, tradesFeeCents } from "@/lib/trades-money";
6	import { computeQuoteTotals } from "@shared/trades-gst";
7	import { TRADES_THEME as T } from "@/lib/trades-theme";
8	
9	type DraftLine = { id: number; description: string; qty: string; unitPrice: string };
10	
11	const money = formatNzd; // canonical NZD formatter (Intl en-NZ) — see trades-money.ts
12	const inputStyle = { width: "100%", boxSizing: "border-box" as const, border: "1px solid rgba(6,21,14,.16)", borderRadius: 12, padding: "12px 13px", font: "inherit", background: "#fff", color: T.INK };
13	
14	export default function QuoteBuilder() {
15	  const [, setLocation] = useLocation();
16	  const queryClient = useQueryClient();
17	  const [clientId, setClientId] = useState("");
18	  const [lines, setLines] = useState<DraftLine[]>([{ id: 1, description: "", qty: "1", unitPrice: "" }]);
19	  const [depositEnabled, setDepositEnabled] = useState(false);
20	  const [depositType, setDepositType] = useState<"percent" | "fixed">("percent");
21	  const [depositValue, setDepositValue] = useState("20");
22	  const [notes, setNotes] = useState("");
23	  const [created, setCreated] = useState<any>(null);
24	  const [error, setError] = useState("");
25	
26	  const { data: clients = [] } = useQuery<any[]>({
27	    queryKey: ["/api/trades/clients"],
28	    queryFn: () => tradesFetch("/api/trades/clients").then(r => r.ok ? r.json() : []),
29	  });
30	  const { data: auth } = useQuery<any>({
31	    queryKey: ["/api/auth/me", "trades-quote"],
32	    queryFn: () => tradesFetch("/api/auth/me").then(r => r.ok ? r.json() : null),
33	  });
34	
35	  const gstMode = auth?.user?.tradeGstMode === "exclusive" ? "exclusive" : "inclusive";
36	  const totals = useMemo(() => {
37	    const lineInputs = lines.map(line => ({
38	      qty: Math.max(0, Number(line.qty) || 0),
39	      unitPriceCents: Math.max(0, Math.round((Number(line.unitPrice) || 0) * 100)),
40	    }));
41	    const depositInput = depositEnabled
42	      ? depositType === "percent"
43	        ? Number(depositValue) || 0
44	        : Math.round((Number(depositValue) || 0) * 100)
45	      : undefined;
46	    const computed = computeQuoteTotals(lineInputs, {
47	      gstRegistered: !!auth?.user?.gstRegistered,
48	      gstMode,
49	      depositEnabled,
50	      depositType: depositEnabled ? depositType : undefined,
51	      depositValue: depositInput,
52	    });
53	    return {
54	      total: computed.totalCents,
55	      gst: computed.gstCents,
56	      net: computed.subtotalCents,
57	      deposit: computed.depositCents ?? 0,
58	    };
59	  }, [lines, auth?.user?.gstRegistered, gstMode, depositEnabled, depositType, depositValue]);
60	
61	  const createQuote = useMutation({
62	    mutationFn: async () => {
63	      setError("");
64	      const lineItems = lines.map(line => {
65	        const qty = Number(line.qty);
66	        const unitPriceCents = Math.round(Number(line.unitPrice) * 100);
67	        return { description: line.description.trim(), qty, unitPriceCents, lineTotalCents: Math.round(qty * unitPriceCents) };
68	      });
