    siteAddress: client.siteAddress ?? "",
    preferredChannel: (client.preferredChannel === "whatsapp" || client.preferredChannel === "sms") ? client.preferredChannel : "email",
    notes: client.notes ?? "",
  });
  setEditing(true);
};

return (
