1	import { useMemo, useState } from "react";
2	import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
3	import { useLocation } from "wouter";
4	import { tradesFetch, tradesHeaders } from "@/lib/trades-api";
5	import { formatNzd, tradesFeeCents } from "@/lib/trades-money";
6	import { computeQuoteTotals } from "@shared/trades-gst";
7	import { TRADES_THEME as T } from "@/lib/trades-theme";
8	
9	type DraftLine = { id: number; description: string; qty: string; unitPrice: string };
10	
11	const money = formatNzd; // canonical NZD formatter (Intl en-NZ) — see trades-money.ts
12	const inputStyle = { width: "100%", boxSizing: "border-box" as const, border: "1px solid rgba(4,13,109,.16)", borderRadius: 12, padding: "12px 13px", font: "inherit", background: "#fff", color: T.INK };
13	
14	export default function QuoteBuilder({ embedded = false, onClose }: { embedded?: boolean; onClose?: () => void } = {}) {
15	  const [, setLocation] = useLocation();
16	  const queryClient = useQueryClient();
17	  // When rendered inside the trades terminal we must never leave the terminal page:
18	  // "back" returns to the terminal's home screen in-place instead of routing away.
19	  const goBack = () => { if (embedded && onClose) { onClose(); return; } setLocation("/trades/terminal"); };
20	  // Embedded fills (and scrolls within) the terminal screen; standalone is a full page.
21	  const wrapStyle = {
22	    ...(embedded ? { height: "100%", overflowY: "auto" as const, WebkitOverflowScrolling: "touch" as const } : { minHeight: "100vh" }),
23	    background: T.OFFW, padding: "22px 16px 96px", color: T.INK, fontFamily: "Outfit, system-ui, sans-serif",
24	  };
25	  const [clientId, setClientId] = useState("");
26	  const [lines, setLines] = useState<DraftLine[]>([{ id: 1, description: "", qty: "1", unitPrice: "" }]);
27	  const [depositEnabled, setDepositEnabled] = useState(false);
28	  const [depositType, setDepositType] = useState<"percent" | "fixed">("percent");
29	  const [depositValue, setDepositValue] = useState("20");
30	  const [notes, setNotes] = useState("");
31	  const [created, setCreated] = useState<any>(null);
32	  const [error, setError] = useState("");
33	
34	  const { data: clients = [] } = useQuery<any[]>({
35	    queryKey: ["/api/trades/clients"],
36	    queryFn: () => tradesFetch("/api/trades/clients").then(r => r.ok ? r.json() : []),
37	  });
38	  const { data: auth } = useQuery<any>({
39	    queryKey: ["/api/auth/me", "trades-quote"],
40	    queryFn: () => tradesFetch("/api/auth/me").then(r => r.ok ? r.json() : null),
41	  });
42	
43	  const gstMode = auth?.user?.tradeGstMode === "exclusive" ? "exclusive" : "inclusive";
44	  const totals = useMemo(() => {
45	    const lineInputs = lines.map(line => ({
46	      qty: Math.max(0, Number(line.qty) || 0),
47	      unitPriceCents: Math.max(0, Math.round((Number(line.unitPrice) || 0) * 100)),
48	    }));
49	    const depositInput = depositEnabled
50	      ? depositType === "percent"
51	        ? Number(depositValue) || 0
52	        : Math.round((Number(depositValue) || 0) * 100)
53	      : undefined;
54	    const computed = computeQuoteTotals(lineInputs, {
55	      gstRegistered: !!auth?.user?.gstRegistered,
56	      gstMode,
57	      depositEnabled,
58	      depositType: depositEnabled ? depositType : undefined,
59	      depositValue: depositInput,
60	    });
61	    return {
62	      total: computed.totalCents,
63	      gst: computed.gstCents,
64	      net: computed.subtotalCents,
65	      deposit: computed.depositCents ?? 0,
66	    };
67	  }, [lines, auth?.user?.gstRegistered, gstMode, depositEnabled, depositType, depositValue]);
68	
69	  const createQuote = useMutation({
70	    mutationFn: async () => {
71	      setError("");
72	      const lineItems = lines.map(line => {
73	        const qty = Number(line.qty);
74	        const unitPriceCents = Math.round(Number(line.unitPrice) * 100);
75	        return { description: line.description.trim(), qty, unitPriceCents, lineTotalCents: Math.round(qty * unitPriceCents) };
76	      });
77	      if (!clientId) throw new Error("Choose a client");
78	      if (lineItems.some(line => !line.description || !Number.isInteger(line.qty) || line.qty <= 0 || line.unitPriceCents < 0)) throw new Error("Complete every line item");
79	      const validUntil = new Date(); validUntil.setDate(validUntil.getDate() + 30);
80	      const selected = clients.find((client: any) => client.id === clientId);
81	      const body = {
82	        clientProfileId: clientId,
83	        lineItems,
84	        deliveryChannel: selected?.preferredChannel || "email",
85	        depositEnabled,
86	        depositType: depositEnabled ? depositType : undefined,
87	        depositValue: depositEnabled ? (depositType === "percent" ? Math.round(Number(depositValue)) : Math.round(Number(depositValue) * 100)) : undefined,
88	        validUntil: validUntil.toISOString(),
89	        notes: notes.trim() || undefined,
90	      };
91	      const response = await fetch("/api/trades/quotes", { method: "POST", headers: { "Content-Type": "application/json", ...tradesHeaders() }, body: JSON.stringify(body) });
92	      if (!response.ok) throw new Error(await response.json().then(d => d.message).catch(() => "Could not create quote"));
93	      return response.json();
94	    },
95	    onSuccess: quote => { queryClient.invalidateQueries({ queryKey: ["/api/trades/quotes"] }); setCreated(quote); },
96	    onError: (err: any) => setError(err?.message || "Could not create quote"),
97	  });
98	
99	  const updateLine = (id: number, field: keyof DraftLine, value: string) => setLines(current => current.map(line => line.id === id ? { ...line, [field]: value } : line));
100	  const publicUrl = created ? `${window.location.origin}/trades/quote/${created.token}` : "";
101	  const downloadCreatedPdf = async () => {
102	    if (!created?.id) return;
103	    const response = await fetch(`/api/trades/quotes/${created.id}/pdf`, { headers: tradesHeaders() });
104	    if (!response.ok) {
105	      setError(await response.json().then(d => d.message).catch(() => "Could not download PDF"));
106	      return;
107	    }
108	    const blob = await response.blob();
109	    const url = URL.createObjectURL(blob);
110	    const link = document.createElement("a");
111	    link.href = url;
112	    link.download = `quote-${String(created.token || created.id).slice(0, 8)}.pdf`;
113	    link.click();
114	    URL.revokeObjectURL(url);
115	  };
116	
117	  if (created) return (
118	    <main style={{ ...wrapStyle, padding: embedded ? "24px 16px 96px" : "40px 18px" }}>
119	      <section style={{ maxWidth: 560, margin: "0 auto", background: "#fff", borderRadius: 22, padding: 24 }}>
120	        <div style={{ color: T.GREEN, fontWeight: 800, fontSize: 12, textTransform: "uppercase", letterSpacing: ".12em" }}>Quote created</div>
121	        <h1 style={{ margin: "10px 0 6px" }}>{money(created.totalCents)}</h1>
122	        <p style={{ color: "#687078" }}>{created.delivered ? "Quote sent to the client." : "Delivery was unavailable. Share this customer link instead."}</p>
123	        <input readOnly value={publicUrl} style={inputStyle} onFocus={e => e.currentTarget.select()} />
124	        <button onClick={() => navigator.clipboard?.writeText(publicUrl)} style={{ ...buttonStyle, marginTop: 12 }}>Copy link</button>
125	        <button onClick={downloadCreatedPdf} style={{ ...buttonStyle, marginTop: 10, background: T.INK }}>Download PDF</button>
126	        {error && <p role="alert" style={{ color: T.RED, fontWeight: 600 }}>{error}</p>}
127	        <button onClick={goBack} style={linkStyle}>Back to terminal</button>
128	      </section>
129	    </main>
130	  );
131	
132	  return (
133	    <main style={wrapStyle}>
134	      <section style={{ maxWidth: 620, margin: "0 auto" }}>
135	        <button onClick={goBack} style={linkStyle}>Back to terminal</button>
136	        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "end", gap: 12 }}>

