52	  amber: { color: C.amber, bg: "rgba(255,176,46,0.18)", fg: "#9A6A00" },
53	  dark: { color: C.panel, bg: "rgba(88,171,255,0.12)", fg: C.panel },
54	  muted: { color: C.mute, bg: "rgba(0,0,0,0.06)", fg: C.mute },
55	};
56	
57	type Channel = "email" | "whatsapp" | "sms";
58	
59	type ClientForm = {
60	  firstName: string;
61	  lastName: string;
62	  email: string;
63	  phone: string;
64	  siteAddress: string;
65	  preferredChannel: Channel;
66	  notes: string;
67	};
68	
69	type EventMeta = {
70	  color: string;
71	  bg: string;
72	  fg: string;
73	  icon: "cash" | "send" | "bell" | "x" | "check" | "page" | "calendar" | "user" | "eye" | "mail" | "message" | "wrench";
74	};
75	
76	function fmtCents(c: number) {
77	  return "$" + (c / 100).toLocaleString("en-NZ", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
78	}
79	
80	function timeOf(value: unknown) {
81	  if (!value) return 0;
82	  const time = new Date(String(value)).getTime();
83	  return Number.isFinite(time) ? time : 0;
84	}
85	
86	function fmtDate(value: string) {
87	  const d = new Date(value);
88	  return d.toLocaleDateString("en-NZ", { day: "2-digit", month: "short" }) + " - " + d.toLocaleTimeString("en-NZ", { hour: "2-digit", minute: "2-digit", hour12: true }).toLowerCase();
89	}
90	
91	function eventLabel(type: string) {
92	  const map: Record<string, string> = {
93	    quote_sent: "quote sent",
94	    quote_dispatched: "quote delivered",
95	    quote_dispatch_failed: "quote not delivered",
96	    quote_viewed: "quote viewed",
97	    quote_accepted: "quote accepted",
98	    quote_declined: "quote declined",
99	    invoice_sent: "invoice created",
100	    invoice_dispatched: "invoice sent",
101	    invoice_email_sent: "invoice emailed",
102	    invoice_email_failed: "email failed",
103	    invoice_overdue: "invoice overdue",
104	    reminder_sent: "reminder sent",
105	    payment_declined: "payment failed",
106	    payment_received: "payment received",
107	    split_share_paid: "split payment received",
108	    paid_external: "marked paid externally",
109	    balance_sent: "balance sent",
110	    job_completed: "job completed",
111	    schedule_created: "recurring invoice started",
112	    schedule_paused: "recurring invoice paused",
113	    schedule_resumed: "recurring invoice resumed",
114	    schedule_updated: "recurring invoice updated",
115	    schedule_terminated: "recurring invoice stopped",
116	    recurring_invoice_generated: "recurring invoice generated",
117	    whatsapp_status: "whatsapp status",
118	  };
119	  return map[type] ?? type.replace(/_/g, " ").toLowerCase();
120	}
121	
122	function eventMeta(type: string): EventMeta {
123	  const t = type.toLowerCase();
124	  if (t.includes("payment_received") || t.includes("paid_external") || t.includes("split_share_paid")) return { ...EVENT_TONES.green, icon: "cash" };
125	  if (t.includes("accepted") || t.includes("completed") || t.includes("created") || t.includes("generated")) return { ...EVENT_TONES.green, icon: t.includes("schedule") || t.includes("recurring") ? "calendar" : "check" };
126	  if (t.includes("failed") || t.includes("declined") || t.includes("overdue") || t.includes("payment_declined")) return { ...EVENT_TONES.red, icon: "x" };
127	  if (t.includes("reminder")) return { ...EVENT_TONES.amber, icon: "bell" };
128	  if (t.includes("viewed")) return { ...EVENT_TONES.dark, icon: "eye" };
129	  if (t.includes("whatsapp")) return { ...EVENT_TONES.dark, icon: "message" };
130	  if (t.includes("email")) return { ...EVENT_TONES.dark, icon: "mail" };
131	  if (t.includes("schedule") || t.includes("recurring")) return { ...EVENT_TONES.green, icon: "calendar" };
132	  if (t.includes("balance") || t.includes("invoice") || t.includes("quote")) return { ...EVENT_TONES.dark, icon: "send" };
133	  if (t.includes("client")) return { ...EVENT_TONES.dark, icon: "user" };
134	  return { ...EVENT_TONES.muted, icon: "page" };
135	}
136	
137	function eventDetail(event: any) {
138	  const payload = event.payload ?? {};
139	  if (payload.channel) return `via ${payload.channel}`;
140	  if (payload.reason) return String(payload.reason);
141	  if (payload.frequency) return `${payload.frequency} - ${fmtCents(payload.amountCents ?? 0)}`;
142	  if (payload.status) return String(payload.status);
143	  if (payload.share && payload.of) return `share ${payload.share} of ${payload.of}`;
144	  if (payload.amountCents) return fmtCents(payload.amountCents);
145	  return "";
146	}
147	
148	function EventIcon({ type }: { type: string }) {
149	  const meta = eventMeta(type);
