export default function QuoteBuilder() {
  const [, setLocation] = useLocation();
  const exit = () => setLocation("/trades/terminal");
  return (
    <div className="tp-viewport">
      <style>{TP_TERM_CSS}</style>
      <QuoteScreen onCancel={exit} onExit={exit} />
    </div>
  );
}

